#pragma once
#include "modules/login_page/contract.h"
#include <QFormLayout>
#include <QLineEdit>
namespace Blueprint_Login_Demo {
class LoginPage final : public Module_d6e34a00df0b18b6 {
public:
    explicit LoginPage(QWidget *parent = nullptr) : Module_d6e34a00df0b18b6(parent) {
        auto *layout = new QFormLayout(this);
        username = new QLineEdit(this);
        username->setObjectName("username");
        password = new QLineEdit(this);
        password->setObjectName("password");
        password->setEchoMode(QLineEdit::Password);
        layout->addRow("Username", username);
        layout->addRow("Password", password);
    }
    Outputs execute(const Inputs &) override {
        return {{"username", username->text()}, {"password", password->text()}};
    }
private:
    QLineEdit *username;
    QLineEdit *password;
};
}

#include "modules/login_page/implementation/login_page.h"
#include <QtTest>
using namespace Blueprint_Login_Demo;
class LoginPageTest final : public QObject {
    Q_OBJECT
private slots:
    void masksPassword() {
        LoginPage page;
        auto *password = page.findChild<QLineEdit *>("password");
        QVERIFY(password);
        QCOMPARE(password->echoMode(), QLineEdit::Password);
    }
    void returnsEnteredCredentials() {
        LoginPage page;
        auto *username = page.findChild<QLineEdit *>("username");
        auto *password = page.findChild<QLineEdit *>("password");
        QVERIFY(username);
        QVERIFY(password);
        Module_d6e34a00df0b18b6 &contract = page;
        QCOMPARE(contract.execute({}), (Outputs{{"username", QString()}, {"password", QString()}}));
        username->setText("demo");
        password->setText("secret");
        QCOMPARE(contract.execute({}), (Outputs{{"username", "demo"}, {"password", "secret"}}));
    }
};
QTEST_MAIN(LoginPageTest)
#include "tst_login_page.moc"

#pragma once
#include "modules/authenticate/contract.h"
namespace Blueprint_Login_Demo {
class Authenticate final : public Module_20dc65af899cb0b5 {
public:
    using Module_20dc65af899cb0b5::Module_20dc65af899cb0b5;
    Outputs execute(const Inputs &inputs) override {
        const bool accepted = inputs.value("username").toString() == "demo"
            && inputs.value("password").toString() == "secret";
        return {{"authenticated", accepted},
                {"message", accepted ? QString("Welcome, demo") : QString("Invalid credentials")}};
    }
};
}

#include "modules/authenticate/implementation/authenticate.h"
#include <QtTest>
using namespace Blueprint_Login_Demo;
class AuthenticateTest final : public QObject {
    Q_OBJECT
private slots:
    void credentials_data() {
        QTest::addColumn<Inputs>("inputs");
        QTest::addColumn<bool>("accepted");
        QTest::newRow("valid") << Inputs{{"username", "demo"}, {"password", "secret"}} << true;
        QTest::newRow("wrong-password") << Inputs{{"username", "demo"}, {"password", "bad"}} << false;
        QTest::newRow("wrong-user") << Inputs{{"username", "other"}, {"password", "secret"}} << false;
        QTest::newRow("empty-user") << Inputs{{"username", ""}, {"password", "secret"}} << false;
        QTest::newRow("empty-password") << Inputs{{"username", "demo"}, {"password", ""}} << false;
        QTest::newRow("missing") << Inputs{} << false;
    }
    void credentials() {
        QFETCH(Inputs, inputs);
        QFETCH(bool, accepted);
        Authenticate module;
        Module_20dc65af899cb0b5 &contract = module;
        const Outputs output = contract.execute(inputs);
        QCOMPARE(output.value("authenticated").toBool(), accepted);
        QCOMPARE(output.value("message").toString(),
                 accepted ? QString("Welcome, demo") : QString("Invalid credentials"));
        QVERIFY(!output.contains("password"));
    }
};
QTEST_MAIN(AuthenticateTest)
#include "tst_authenticate.moc"

#pragma once
#include "modules/authenticated/contract.h"
namespace Blueprint_Login_Demo {
class Authenticated final : public Module_40c041842ccbe556 {
public:
    bool decide(const Inputs &inputs) const override {
        return inputs.value("authenticated", false).toBool();
    }
};
}

#include "modules/authenticated/implementation/authenticated.h"
#include "modules/authenticate/implementation/authenticate.h"
#include "modules/login_page/implementation/login_page.h"
#include <QtTest>
using namespace Blueprint_Login_Demo;
class AuthenticatedTest final : public QObject {
    Q_OBJECT
private slots:
    void branches_data() {
        QTest::addColumn<Inputs>("inputs");
        QTest::addColumn<bool>("expected");
        QTest::newRow("true") << Inputs{{"authenticated", true}} << true;
        QTest::newRow("false") << Inputs{{"authenticated", false}} << false;
        QTest::newRow("missing") << Inputs{} << false;
    }
    void branches() {
        QFETCH(Inputs, inputs);
        QFETCH(bool, expected);
        Authenticated decision;
        const Module_40c041842ccbe556 &contract = decision;
        QCOMPARE(contract.decide(inputs), expected);
    }
    void loginFlow_data() {
        QTest::addColumn<QString>("username");
        QTest::addColumn<QString>("password");
        QTest::addColumn<QString>("terminal");
        QTest::newRow("success") << QString("demo") << QString("secret") << QString("success");
        QTest::newRow("bad-password") << QString("demo") << QString("bad") << QString("failure");
        QTest::newRow("empty-user") << QString() << QString("secret") << QString("failure");
        QTest::newRow("empty-password") << QString("demo") << QString() << QString("failure");
    }
    void loginFlow() {
        QFETCH(QString, username);
        QFETCH(QString, password);
        QFETCH(QString, terminal);
        LoginPage page;
        auto *userField = page.findChild<QLineEdit *>("username");
        auto *passwordField = page.findChild<QLineEdit *>("password");
        QVERIFY(userField);
        QVERIFY(passwordField);
        userField->setText(username);
        passwordField->setText(password);
        Authenticate authenticate;
        Authenticated decision;
        const Outputs result = authenticate.execute(page.execute({}));
        const QString actualTerminal = decision.decide(result) ? "success" : "failure";
        QCOMPARE(actualTerminal, terminal);
        QCOMPARE(result.value("message").toString(),
                 terminal == "success" ? QString("Welcome, demo") : QString("Invalid credentials"));
    }
};
QTEST_MAIN(AuthenticatedTest)
#include "tst_authenticated.moc"
